select `p`.`ppl_correlativo` AS `id_planilla`,`p`.`ppl_numero` AS `periodo`,`p`.`ppl_fecha_inicio` AS `ppl_fecha_inicio`,`p`.`ppl_fecha_final` AS `ppl_fecha_final`,`p`.`ppl_fecha_pago` AS `ppl_fecha_pago`,`p`.`ppl_porcentaje_pago` AS `porcentaje`,`p`.`ppl_estado_proceso` AS `estado`,`p`.`ppl_fecha_generacion` AS `ppl_fecha_generacion`,`p`.`ppl_fecha_cierre` AS `ppl_fecha_cierre`,`p`.`ppl_usuario_genera` AS `ppl_usuario_genera`,`p`.`ppl_usuario_cierra` AS `ppl_usuario_cierra`,(select count(0) from `apps_rpjepq`.`rpj_prc_nomina_ingreso` where `apps_rpjepq`.`rpj_prc_nomina_ingreso`.`nin_id_planilla` = `p`.`ppl_correlativo` and `apps_rpjepq`.`rpj_prc_nomina_ingreso`.`nin_tipo_manejo` = 2) AS `total_pensionados`,(select ifnull(sum(`apps_rpjepq`.`rpj_prc_nomina_ingreso`.`nin_valor`),0) from `apps_rpjepq`.`rpj_prc_nomina_ingreso` where `apps_rpjepq`.`rpj_prc_nomina_ingreso`.`nin_id_planilla` = `p`.`ppl_correlativo` and `apps_rpjepq`.`rpj_prc_nomina_ingreso`.`nin_tipo_manejo` = 2) AS `total_ingresos`,(select ifnull(sum(`apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_valor`),0) from `apps_rpjepq`.`rpj_prc_nomina_descuento` where `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_planilla` = `p`.`ppl_correlativo` and `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_tipo_manejo` = 2) AS `total_descuentos` from `apps_rpjepq`.`rpj_cat_parametro_planilla` `p` where `p`.`ppl_tipo_planilla` = 2 order by `p`.`ppl_numero` desc
